-- Splynn Dimensional Market: the Kittani Centipede and Flying Fox power armours (printed 164-170).
-- 2 vehicle rows, with 25 locations and 16 weapon entries.
--
-- One-off data script, run once per environment. NOT a migration - it adds
-- rows, not schema.
--
--   node scripts/d1-apply.mjs --local apps/character-creator/db/~363-splynn-power-armor.sql
--
-- Written by scripts/vessel-sql.mjs from 1 worker file(s). Every value
-- is printable ASCII, every row cites its book, and a Main Body location
-- agrees with its vehicle's mdc_main_body.

INSERT OR IGNORE INTO vehicles (slug, name, system, vehicle_class, crew, passengers, speed_ground, speed_air, speed_water, dimensions, weight_tons, mdc_main_body, is_mega_damage, ar, cost, cost_note, description, source_book) VALUES
  ('kittani-centipede-power-armor', 'Kittani Centipede Power Armor (CPA-1)', 'rifts', 'power-armor', 'One', NULL, 'Running 30 mph (48 km) maximum without tiring the pilot; climbs rough surfaces at 85% and sheer ones at 60%. Leaping is not possible while joined to the lower body. The detached light suit runs 40 mph (64 km) and leaps 50 feet (15 m) high or lengthwise.', 'Not possible. The detached light suit can fly only with a jet pack.', 'Walks the bottom at 25% of its running speed (7.5 mph/12 km). Depth 2000 feet (610 m).', 'Height 12 feet in total: the lower body rides 2 feet off the ground on 3-foot segments, and the upper body rises 7 feet (2.1 m) above that. Width 10 feet (3 m) foot to foot, 8 feet (2.4 m) across the shoulders. Length 30 feet (9.1 m); each of the ten segments is 3 feet long.', '10 tons fully loaded; 5 tons without the detachable segments', 375, 1, NULL, NULL, 'NO PRICE. "Not available." The book says a sale would fetch at least 25 million credits, and more likely double that.', 'A centaur-shaped Kittani heavy anti-armor suit: the pilot rides an armored humanoid upper body mounted on the second of ten two-legged segments of a centipede-like lower body, whose head carries biting jaws and two laser eyes. Missile tubes along the segments make it a long-range anti-armor and anti-aircraft platform, usually screened by Serpent power armor against infantry. Only the first three segments are needed to move; the other seven can be dropped when damaged, or dropped as timed missile mines. In an emergency the pilot sheds the heavy plates and leaves the lower body in a light suit equal to the K-Universal without its jet pack. Robotic P.S. 46. Nuclear power, 20-year life. A small cargo space under the upper body holds a rifle, a sidearm and a survival pack.', 'Rifts World Book 21: Splynn Dimensional Market p.164-167'),
  ('kittani-flying-fox-power-armor', 'Kittani Flying Fox Power Armor (FFPA)', 'rifts', 'power-armor', 'One', NULL, 'Running 50 mph (80 km/h) maximum, tiring the pilot at a tenth of the normal rate. Leaps 15 feet (4.6 m) high or across unassisted; a thruster-assisted leap reaches 200 feet (61 m) high or 300 feet (91.5 m) long.', 'Hover up to 300 feet (91.5 m) or fly up to 600 mph (960 km); ceiling 20,000 feet (6096 m), above which flight is erratic (-30% piloting, -50% on trick maneuvers). Unlimited range, but the thrusters must cool after 12 hours at top speed or 36 at cruising speed. Can operate in space.', 'Swims 5 mph (8 km/h); walks the bottom at 12.5 mph (20 km); on its thrusters 100 mph (160 km) on the surface or 70 mph (112.6 km) underwater. Depth 1000 feet (305 m).', 'Height 8 feet (2.4 m), the wings adding 3 feet (0.9 m). Width 4 feet (1.2 m); the wings add 10 feet (3 m), 20 feet (6 m) at full extension. Length 5 feet (1.5 m) with thrusters.', '1000 lbs (450 kg)', 350, 1, NULL, NULL, 'NO PRICE. "Not available." The book says a sale would fetch at least 30 million credits, and more likely double that.', 'A bat-winged Kittani aerial assault suit built to answer the Coalition Super SAMAS, with back and leg thrusters that outpace nearly any Earth power armor; the wings fold back at top speed. Its black wings hide mini-missile pods and lasers, and their edges are Vibro-Blades. It carries the usual Kittani plasma axe and combat shield. The Splugorth would not name it for the bat, a form vampires take. Long in service and often seen above Splynn and the Kittani''s Ki-Talan, flying patrols and seek-and-destroy missions. Robotic P.S. 40. Nuclear power, 20-year life. No cargo space beyond what is strapped on.', 'Rifts World Book 21: Splynn Dimensional Market p.167-170');

INSERT OR IGNORE INTO vehicle_locations (vehicle_slug, location, mdc, mdc_note, ordinal) VALUES
  ('kittani-centipede-power-armor', 'Short-Range Missile Tubes (18)', 20, 'Each. Lower body: two on every segment but the first. Called shot only, -2 to strike.', 1),
  ('kittani-centipede-power-armor', 'Legs (20)', 30, 'Each. Lower body: two per segment. Called shot only, -2 to strike. Losing two legs of the main three segments with half the rest detached costs a third of its speed; three or more lost there immobilize it.', 2),
  ('kittani-centipede-power-armor', 'Centipede Jaws', 120, 'Lower body.', 3),
  ('kittani-centipede-power-armor', 'Laser Eyes (2)', 50, 'Each. Lower body. Called shot only, -2 to strike.', 4),
  ('kittani-centipede-power-armor', 'Head (Lower Body)', 260, 'Not essential, but destroying it takes the jaws and the eye lasers with it.', 5),
  ('kittani-centipede-power-armor', 'Body Segments (10)', 150, 'Each. Losing any of the last seven costs only firepower; losing one of the first three immobilizes the armor.', 6),
  ('kittani-centipede-power-armor', 'Shoulder Plates & Mini-Missile Launchers (2)', 150, 'Each. Upper body.', 7),
  ('kittani-centipede-power-armor', 'Forearms (2)', 100, 'Each. Upper body.', 8),
  ('kittani-centipede-power-armor', 'Energy Lance', 90, 'Upper body.', 9),
  ('kittani-centipede-power-armor', 'Class Two Rocket Shield', 150, 'Upper body.', 10),
  ('kittani-centipede-power-armor', 'Head (Upper Body)', 100, 'Called shot only, -4 to strike. Destroying it ends all sensors and the power armor combat bonuses.', 11),
  ('kittani-centipede-power-armor', 'Main Body', 375, 'Upper body. Depleting it shuts the armor down.', 12),
  ('kittani-flying-fox-power-armor', 'Hidden Mini-Missile Pods (4)', 45, 'Each; two in each wing. Hard to spot: -4 to strike even on a called shot.', 1),
  ('kittani-flying-fox-power-armor', 'Wing Lasers (2)', 35, 'Each. Hard to spot: -4 to strike even on a called shot.', 2),
  ('kittani-flying-fox-power-armor', 'Wing Vibro-Blades (2)', 25, 'Each.', 3),
  ('kittani-flying-fox-power-armor', 'Main Thrusters (2)', 150, 'Each; on the back. One lost cuts flight speed 35%; both lost leaves the leg thrusters at a tenth of speed.', 4),
  ('kittani-flying-fox-power-armor', 'Secondary Thrusters (4)', 50, 'Each; two on each leg. With every thruster gone the armor falls and cannot fly.', 5),
  ('kittani-flying-fox-power-armor', 'Wings (2)', 150, 'Each. One lost: -25% piloting, -2 dodge. Both lost: top speed down 25% and the penalties doubled.', 6),
  ('kittani-flying-fox-power-armor', 'Legs (2)', 160, 'Each.', 7),
  ('kittani-flying-fox-power-armor', 'Shoulders (2)', 120, 'Each.', 8),
  ('kittani-flying-fox-power-armor', 'Arms (2)', 85, 'Each.', 9),
  ('kittani-flying-fox-power-armor', 'Plasma Axe', 100, NULL, 10),
  ('kittani-flying-fox-power-armor', 'Class One Shield and Mini-Missile Launcher', 200, NULL, 11),
  ('kittani-flying-fox-power-armor', 'Head', 110, 'Called shot only, -4 to strike. Destroying it ends all sensors and the power armor combat bonuses.', 12),
  ('kittani-flying-fox-power-armor', 'Main Body', 350, 'Depleting it shuts the armor down; in flight it crashes.', 13);

INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('kittani-centipede-power-armor', 1, 'Short-Range Missile Tubes', 'By missile type; standard issue is half armor-piercing and half plasma, each 1D6x10 M.D.', 1, 'By missile type, typically 3 to 5 miles (4.8 to 8 km)', 'One at a time, or volleys of 2, 3, 4, 8 or 12', 'Three per tube, 54 in all', NULL, 'Anti-aircraft first, anti-armor second. Two tubes on each lower-body segment but the first, angled up, out and back. Enhanced missiles from Coalition War Campaign may be fitted.'),
  ('kittani-centipede-power-armor', 2, 'Shoulder Mini-Missile Launchers', 'By mini-missile type; standard issue armor-piercing, 1D4x10 M.D.', 1, 'By missile type, typically one mile (1.6 km)', 'One at a time, or volleys of 2, 3, 4 or 8', 'Three per launcher, six in all', NULL, 'Hidden under panels in the shoulder plates; lost when the pilot leaves in the light suit.'),
  ('kittani-centipede-power-armor', 3, 'Eye Lasers', '3D6 M.D. a blast, or 6D6 M.D. a dual blast', 1, '3,000 feet (914 m)', 'Equal to the pilot''s hand to hand attacks', 'Effectively unlimited, from the nuclear plant', NULL, 'In the lower body''s head; the secondary anti-aircraft weapon.'),
  ('kittani-centipede-power-armor', 4, 'Energy Lance', '3D6 M.D. a long-range shot, or 6D6 M.D. at half range; 2D4 M.D. as a stabbing or blunt weapon', 1, '6000 feet (1828 m), or 3000 feet (915 m) at double damage; six-foot reach in melee', 'Equal to the pilot''s hand to hand attacks', '40 shots; recharges one blast every six minutes (10 an hour)', '+2 to strike on called shots, on top of power armor bonuses', 'The standard hand weapon; a sniper weapon first. Weighs 20 lbs (9 kg).'),
  ('kittani-centipede-power-armor', 5, 'Class Two Rocket Shield', '2D4 M.D. shield strike; 3D4x10 M.D. multiple-warhead missile', 1, 'Close combat, or two miles (3.2 km) for the missile', 'Shield strikes equal to the pilot''s hand to hand attacks; one missile', 'One missile', NULL, 'Large and awkward. Parries physical attacks and missiles but not energy blasts; a parry halves the damage to the shield. Weighs 100 lbs (45 kg).'),
  ('kittani-centipede-power-armor', 6, 'Hand to Hand Combat', 'Restrained punch 1D6 M.D.; full strength punch 3D6 M.D.; power punch 6D6 M.D. (two attacks); leg jab 1D4 M.D.; front mandible bite 4D6 M.D.; body block/tackle 1D4 M.D.', 1, 'Hand to hand', NULL, NULL, '+1 initiative, +2 strike and parry, on top of Power Armor Combat and hand to hand skill', 'For the full armor; the light suit fights by the robot combat skill listing instead.'),
  ('kittani-centipede-power-armor', 7, 'Hand-Held Weapons', NULL, 0, NULL, NULL, NULL, NULL, 'A hand-held weapon can stand in or be kept as a backup. Weapons stowed in the cargo space cannot be reached while the pilot is inside.'),
  ('kittani-centipede-power-armor', 8, 'Sensory Systems', NULL, 0, NULL, NULL, NULL, '+2 strike, long-range weapon systems only (not melee)', 'Full optics: laser targeting, 1000x telescopic, passive night vision, thermo-imaging, infrared, ultraviolet and polarized vision, plus the standard power armor features.'),
  ('kittani-flying-fox-power-armor', 1, 'Double-Bladed Plasma Axe', '1D4x10 M.D. energized strike or short-range plasma blast; 1D4 M.D. blunt', 1, 'Close combat, or 200 feet (61 m) for the blast', 'Equal to the pilot''s hand to hand attacks', 'Effectively unlimited from the armor; on an E-clip, 60 minutes or 6 blasts at half damage', NULL, 'Standard on many light Kittani suits. Weighs 20 lbs (9 kg).'),
  ('kittani-flying-fox-power-armor', 2, 'Class One Combat Shield and Mini-Missile Launcher', '3D4 M.D. shield strike; 1D4x10 M.D. per armor-piercing mini-missile (any type may be loaded)', 1, 'Close combat, or one mile (1.6 km) for the missiles', 'Shield strikes equal to the pilot''s hand to hand attacks; missiles one at a time or in volleys of 2, 3 or 4', 'Four mini-missiles', NULL, 'Parries physical attacks, missiles and energy blasts, the last at -4; a parry halves the damage to the shield. Weighs 70 lbs (31.5 kg).'),
  ('kittani-flying-fox-power-armor', 3, 'Wing Mini-Missile Launchers (4)', 'By mini-missile type; standard issue armor-piercing, 1D4x10 M.D.', 1, 'One mile (1.6 km)', 'One at a time, or volleys of 2, 3, 4, 6, 8, 12 or all 16', 'Four per pod, 16 in all', NULL, 'Two black-painted pods on each wing, hard to pick out.'),
  ('kittani-flying-fox-power-armor', 4, 'Wing Lasers (2)', '3D6 M.D., or 6D6 M.D. per dual blast against a target 12 feet (3.6 m) wide or larger', 1, '2000 feet (610 m)', 'Equal to the pilot''s hand to hand attacks', 'Effectively unlimited, from the nuclear plant', NULL, 'One fixed forward on top of each wing; the armor turns to aim.'),
  ('kittani-flying-fox-power-armor', 5, 'Wing Vibro-Blades (2)', '2D6 M.D. at cruising speed, 5D6 M.D. at 400 mph (640 km) or more; unenergized 1D4 M.D. cruising, 2D4 M.D. at 400 mph or more', 1, 'Close-range aerial combat', 'Only at the start of a melee round, with no other close combat attack that round', 'Effectively unlimited', NULL, 'Fly-by slashes; -25% piloting at high speed. A failed piloting or strike roll means a collision: 1D4x10 M.D. to wing and target at cruising speed, 1D6x10 M.D. at 400 mph or more.'),
  ('kittani-flying-fox-power-armor', 6, 'Hand to Hand Combat', 'Restrained punch 1D6 M.D.; full strength punch, kick or shield strike 3D4 M.D.; power punch 4D6 M.D. (two attacks); leap kick 4D6 M.D. (all attacks, start of round only); thruster-assisted leap kick 1D4x10 M.D. (all attacks, start of round only); body block/tackle 1D4 M.D.; full speed flying ram 4D6 M.D. (three attacks, 1D4 M.D. to the attacker)', 1, 'Hand to hand', NULL, NULL, '+1 attack per melee, +3 initiative, +1 strike and parry, +2 dodge in flight, on top of Power Armor Combat and hand to hand skill', NULL),
  ('kittani-flying-fox-power-armor', 7, 'Hand-Held Weapons', NULL, 0, NULL, NULL, NULL, NULL, 'One extra weapon may be carried as a substitute or backup, strapped to the outside of the armor, since there is no cargo space.'),
  ('kittani-flying-fox-power-armor', 8, 'Sensory Systems', NULL, 0, NULL, NULL, NULL, '+2 strike, long-range weapon systems only (not melee)', 'Full optics: laser targeting, 1000x telescopic, passive night vision, thermo-imaging, infrared, ultraviolet and polarized vision, plus the standard power armor features.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 2 machines are in' AS assertion, count(*) AS got, 2 AS want
  FROM vehicles WHERE slug IN ('kittani-centipede-power-armor', 'kittani-flying-fox-power-armor');
SELECT 'their 25 locations are in' AS assertion, count(*) AS got, 25 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('kittani-centipede-power-armor', 'kittani-flying-fox-power-armor');
SELECT 'their 16 weapon entries are in' AS assertion, count(*) AS got, 16 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('kittani-centipede-power-armor', 'kittani-flying-fox-power-armor');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('kittani-centipede-power-armor', 'kittani-flying-fox-power-armor') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

